steps.script:
var dd = tree.root.get_node_or_null("/root/DisembarkDialog")
if dd == null:
	return false
dd.get_ok_button().pressed.emit()
return true

var wb = GameState.get_unit("U_WARBOSS_T")
var m = wb.get("models", [])
if m.is_empty():
	return false
return m[0].get("position", null) != null

var mc = tree.current_scene.movement_controller
var want := 0
for uid in ["U_BOYZ_T", "U_WARBOSS_T"]:
	for m in GameState.get_unit(uid).get("models", []):
		if m.get("alive", true):
			want += 1
if mc.selected_models.size() != want:
	return "selected %d of %d" % [mc.selected_models.size(), want]
if str(mc.selection_mode) != "MULTI":
	return "selection_mode %s" % str(mc.selection_mode)
return "ok"

var md = tree.current_scene.movement_controller.current_phase.get_active_move_data("U_BOYZ_T")
var dists = md.get("model_distances", {})
var missed := []
for uid in ["U_BOYZ_T", "U_WARBOSS_T"]:
	var models = GameState.get_unit(uid).get("models", [])
	for i in range(models.size()):
		if not models[i].get("alive", true):
			continue
		var key = "%s:%s" % [uid, str(models[i].get("id", "m%d" % (i + 1)))]
		if float(dists.get(key, 0.0)) <= 0.5:
			missed.append(key)
if not missed.is_empty():
	return "did not move: %s" % str(missed)
return "ok"

var pi = PhaseManager.current_phase_instance
var am = pi.active_moves.get("U_BATTLEWAGON_T", {})
return bool(am.get("mode_locked", false))

var d = null
for c in tree.root.get_children():
	if c is Window and c.visible and str(c.name).to_lower().contains("reroll"):
		d = c
if d == null:
	return "NO REROLL DIALOG"
return "%s|%s" % [str(d.name), str(d.has_meta("tutorial_exit_button"))]

var phase = PhaseManager.get_current_phase_instance()
var md = phase.get_active_move_data("U_BATTLEWAGON_T")
var dists = md.get("model_distances", {})
for k in dists:
	return float(dists[k])
return -1.0

var o = tree.root.get_node("/root/TutorialOverlay")
var t = o.current_body_text()
return t.contains("[Q]") and t.contains("[E]") and t.contains("costs no inches")

var phase = PhaseManager.get_current_phase_instance()
var md = phase.get_active_move_data("U_BATTLEWAGON_T")
var dists = md.get("model_distances", {})
for k in dists:
	return float(dists[k])
return -1.0
